//   CONTACT_EMAIL        email shown on the About / Privacy pages                  — optional
const ADS = {
  client: (process.env.ADSENSE_CLIENT || "").trim().replace(/^pub-/, "ca-pub-"),
  side: (process.env.ADSENSE_SLOT_SIDE || "").trim(),
  bottom: (process.env.ADSENSE_SLOT_BOTTOM || "").trim(),
};
if (ADS.client && !/^ca-pub-\d{10,20}$/.test(ADS.client)) { console.log("[ads] ADSENSE_CLIENT looks wrong (expected ca-pub-1234567890123456) — ads disabled"); ADS.client = ""; }
const CONTACT = (process.env.CONTACT_EMAIL || "").trim();
const escH = s => String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
function withAds(html) {
  if (!ADS.client) return html.replace("<!--ADS_HEAD-->", "");
  const cfg = { client: ADS.client, side: /^\d+$/.test(ADS.side) ? ADS.side : "", bottom: /^\d+$/.test(ADS.bottom) ? ADS.bottom : "" };
  return html.replace("<!--ADS_HEAD-->",
    `<meta name="google-adsense-account" content="${ADS.client}">\n<script>window.IR_ADS=${JSON.stringify(cfg)}</script>\n` +
    `<script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=${ADS.client}" crossorigin="anonymous"></script>`);
}
app.get("/ads.txt", (req, res) => {
  res.type("text/plain");
  if (!ADS.client) return res.send("# Ads are not set up yet (set ADSENSE_CLIENT on the server)\n");
  res.send(`google.com, ${ADS.client.replace("ca-", "")}, DIRECT, f08c47fec0942fa0\n`);
});
