// ---------- player profile ----------
app.get("/api/player/:username", (req, res) => {
  const u = store.get(userKey(req.params.username));
  if (!u) return res.status(404).json({ error: "No such player" });
  const users = store.values("user:");
  const lower = u.username.toLowerCase();
  const likes = users.filter((o) => o.likes && o.likes[lower]).length;
  const bestTotal = u.top && u.top[0] ? u.top[0].total : -1;
  const rank = bestTotal < 0 ? null : 1 + users.filter((o) => o.top && o.top[0] && o.top[0].total > bestTotal).length;
  const seen = u.seen || {};
  const byRarity = {};
  for (const b of game.BADGES) {
    byRarity[b.rar] = byRarity[b.rar] || { found: 0, total: 0 };
    byRarity[b.rar].total++;
    if (seen[b.id]) byRarity[b.rar].found++;
  }
  const found = game.BADGES.filter((b) => seen[b.id]);
  const rarest = found.sort((a, b) => a.p - b.p).slice(0, 3).map((b) => b.id);
  const favorite = Object.entries(seen).filter(([id]) => { const b = game.BADGES.find((x) => x.id === id); return b && b.p < 0.1; })
    .sort((a, b) => b[1] - a[1])[0];
  const dk = dayKey(), wk = weekKey();
  res.json({
    ...publicProfile(u),
    created: u.created || null,
    rolls: u.rolls || 0,
    life: u.life || 0,
    play: u.play || 0,
    likes,
    rank,
    players: users.length,
    top: (u.top || []).slice(0, 5).map((r) => ({ n: r.n, total: r.total, pct: r.pct, at: r.at || null })),
    today: u.day && u.day.key === dk ? { n: u.day.n, total: u.day.total, at: u.day.at || null } : null,
    week: u.week && u.week.key === wk ? { n: u.week.n, total: u.week.total, at: u.week.at || null } : null,
    badges: Object.keys(seen).length,
    badgesTotal: game.BADGES.length,
    byRarity,
    rarest,
    favorite: favorite ? { id: favorite[0], count: favorite[1] } : null,
    tiers: u.tiers || {},
  });
});

app.get("/api/player/:username/history", async (req, res) => {
  const u = store.get(userKey(req.params.username));
  if (!u) return res.status(404).json({ error: "No such player" });
  const me = currentUser(req);
  const meL = me ? me.username.toLowerCase() : null;
  const offset = Math.max(0, parseInt(req.query.offset, 10) || 0);
  const limit = Math.min(50, Math.max(1, parseInt(req.query.limit, 10) || 10));
  const hist = await store.histGet(lc(u.username));
  const likes = store.get(rlkKey(u.username)) || {};
  const items = [];
  for (let i = hist.length - 1 - offset; i >= 0 && items.length < limit; i--) {
    const h = hist[i], lk = likes[h.id] || {};
    items.push({ id: h.id, n: h.n, total: h.t, pct: h.p, at: h.at || null, badges: h.b, likes: Object.keys(lk).length, liked: !!(meL && lk[meL]) });
  }
  res.json({ total: u.rolls || 0, stored: hist.length, offset, items, more: offset + limit < hist.length, mine: !!(me && me.username === u.username) });
});

app.post("/api/player/:username/history/:id/like", async (req, res) => {
  const me = currentUser(req);
  if (!me) return res.status(401).json({ error: "Log in to like" });
  const owner = store.get(userKey(req.params.username));
  if (!owner) return res.status(404).json({ error: "No such player" });
  if (owner.username === me.username) return res.status(400).json({ error: "You can't like your own roll" });
  if (limited("rlike:" + me.username.toLowerCase(), 30, 60e3)) return res.status(429).json({ error: "Slow down!" });
  const id = Number(req.params.id);
  const hist = await store.histGet(lc(owner.username));
  if (!hist.some((x) => x.id === id)) return res.status(404).json({ error: "No such roll" });
  const l = lc(me.username);
  const all = store.get(rlkKey(owner.username)) || {};
  const lk = all[id] || {};
  if (lk[l]) delete lk[l]; else lk[l] = true;
  if (Object.keys(lk).length) all[id] = lk; else delete all[id];
  store.set(rlkKey(owner.username), all);
  res.json({ liked: !!lk[l], likes: Object.keys(lk).length });
});

// ---------- leaderboard ----------
app.get("/api/leaderboard", (req, res) => {
  const view = ["day", "week", "all", "badges", "total"].includes(req.query.view) ? req.query.view : "day";
  const me = currentUser(req);
  const users = store.values("user:");
  const likeCount = {};
  for (const u of users) for (const t in u.likes || {}) likeCount[t] = (likeCount[t] || 0) + 1;
  const dk = dayKey(), wk = weekKey();
  let rows = users.map((u) => {
    let pick = null;
    if (view === "day") pick = u.day && u.day.key === dk ? u.day : null;
    else if (view === "week") pick = u.week && u.week.key === wk ? u.week : null;
    else pick = u.top && u.top[0] ? u.top[0] : null;
    const badges = Object.keys(u.seen || {}).length;
    return { ...publicProfile(u), n: pick ? pick.n : null, total: pick ? pick.total : -1, at: pick ? pick.at || null : null, badges, life: u.life || 0, rolls: u.rolls || 0, play: u.play || 0,
      likes: likeCount[u.username.toLowerCase()] || 0, liked: !!(me && me.likes && me.likes[u.username.toLowerCase()]), me: !!(me && me.username === u.username) };
  });
  if (view === "badges") rows = rows.filter((r) => r.badges > 0).sort((a, b) => b.badges - a.badges || b.total - a.total);
  else if (view === "total") rows = rows.filter((r) => r.life > 0).sort((a, b) => b.life - a.life);
  else rows = rows.filter((r) => r.n !== null).sort((a, b) => b.total - a.total);
  res.json({ view, total: game.BADGES.length, rows: rows.slice(0, 100) });
});

app.post("/api/like/:username", (req, res) => {
  const u = currentUser(req);
  if (!u) return res.status(401).json({ error: "Log in to like" });
  const target = String(req.params.username).toLowerCase();
  if (!store.get(userKey(target))) return res.status(404).json({ error: "No such player" });
  if (target === u.username.toLowerCase()) return res.status(400).json({ error: "You can't like yourself" });
  if (limited("like:" + u.username.toLowerCase(), 30, 60e3)) return res.status(429).json({ error: "Slow down!" });
  u.likes = u.likes || {};
  if (u.likes[target]) delete u.likes[target]; else u.likes[target] = true;
  store.set(userKey(u.username), u);
  res.json({ liked: !!u.likes[target] });
});

// ---------- admin panel ----------
function requireAdmin(req, res) {
  const u = currentUser(req);
  if (!isAdmin(u)) { res.status(403).json({ error: "Admins only" }); return null; }
  return u;
}
function sessionsOf(lower) { return store.keys("sess:").filter((k) => (store.get(k) || {}).u === lower); }

app.get("/api/admin/users", (req, res) => {
  if (!requireAdmin(req, res)) return;
  const q = String(req.query.q || "").toLowerCase().slice(0, 32);
  const rows = store.values("user:")
    .filter((u) => !q || u.username.toLowerCase().includes(q))
    .sort((a, b) => (b.created || 0) - (a.created || 0))
    .slice(0, 200)
    .map((u) => ({ username: u.username, rolls: u.rolls || 0, life: u.life || 0, best: u.top && u.top[0] ? u.top[0].n : null,
      badges: Object.keys(u.seen || {}).length, created: u.created || 0, admin: isAdmin(u), sessions: sessionsOf(u.username.toLowerCase()).length }));
  res.json({ rows, count: store.keys("user:").length });
});

app.post("/api/admin/rename", async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const { username, newName } = req.body || {};
  const u = store.get(userKey(username));
  if (!u) return res.status(404).json({ error: "No such player" });
  if (typeof newName !== "string" || !USERNAME_RE.test(newName)) return res.status(400).json({ error: "Username: 3–16 letters, numbers or _" });
  const oldL = u.username.toLowerCase(), newL = newName.toLowerCase();
  if (newL !== oldL && store.get(userKey(newName))) return res.status(409).json({ error: "That username is taken" });
  if (isAdmin(u) && newL !== oldL) return res.status(400).json({ error: "This is an admin account: change ADMIN_USERS on Render first, or only change the capitalization" });
  u.username = newName;
  if (newL !== oldL) {
    store.del(userKey(oldL));
    await store.histMove(oldL, newL);
    const myLikes = store.get(rlkKey(oldL)); if (myLikes) { store.set(rlkKey(newL), myLikes); store.del(rlkKey(oldL)); }
    for (const k of store.keys("rlk:")) { const all = store.get(k); let ch = false; for (const id in all) if (all[id][oldL]) { delete all[id][oldL]; all[id][newL] = true; ch = true; } if (ch) store.set(k, all); }
    for (const k of sessionsOf(oldL)) store.set(k, { ...store.get(k), u: newL });
    for (const k of store.keys("user:")) {
      const o = store.get(k);
      if (o.likes && o.likes[oldL]) { delete o.likes[oldL]; o.likes[newL] = true; store.set(k, o); }
    }
  }
  store.set(userKey(newName), u);
  console.log(`[admin] ${admin.username} renamed ${oldL} -> ${newName}`);
  res.json({ ok: true });
});

app.post("/api/admin/password", async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const { username, password } = req.body || {};
  const u = store.get(userKey(username));
  if (!u) return res.status(404).json({ error: "No such player" });
  if (typeof password !== "string" || password.length < 6 || password.length > 100) return res.status(400).json({ error: "Password: at least 6 characters" });
  Object.assign(u, await hashPassword(password));
  store.set(userKey(u.username), u);
  for (const k of sessionsOf(u.username.toLowerCase())) store.del(k); // log them out everywhere
  console.log(`[admin] ${admin.username} changed the password of ${u.username}`);
  res.json({ ok: true });
});

app.post("/api/admin/delete", async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const u = store.get(userKey((req.body || {}).username));
  if (!u) return res.status(404).json({ error: "No such player" });
  if (u.username.toLowerCase() === admin.username.toLowerCase()) return res.status(400).json({ error: "You can't delete your own account" });
  const l = u.username.toLowerCase();
  store.del(userKey(l));
  await store.histDel(l); store.del(rlkKey(l));
  for (const k of sessionsOf(l)) store.del(k);
  for (const k of store.keys("user:")) { const o = store.get(k); if (o.likes && o.likes[l]) { delete o.likes[l]; store.set(k, o); } }
  console.log(`[admin] ${admin.username} deleted ${u.username}`);
  res.json({ ok: true });
});

app.post("/api/admin/reset", async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const u = store.get(userKey((req.body || {}).username));
  if (!u) return res.status(404).json({ error: "No such player" });
  Object.assign(u, { life: 0, rolls: 0, seen: {}, top: [], last: null, day: null, week: null });
  await store.histDel(lc(u.username)); store.del(rlkKey(u.username));
  store.set(userKey(u.username), u);
  console.log(`[admin] ${admin.username} reset the stats of ${u.username}`);
  res.json({ ok: true });
});

