// Recompute stored scores when the scoring rules change (EP now = official RNGdle values)
const SCORING_VERSION = 3;
function migrateScores() {
  if ((store.get("meta:scoring") || {}).v === SCORING_VERSION) return;
  let n = 0;
  const fix = (r) => { if (r && typeof r.n === "number") { r.total = scoreOf(r.n); if ("pct" in r || r.badges) r.pct = game.topPct(r.total); if (r.badges) r.badges = game.score(r.n).ids; } };
  for (const k of store.keys("user:")) {
    const u = store.get(k);
    (u.top || []).forEach(fix); fix(u.last); fix(u.day); fix(u.week);
    if (u.top) u.top.sort((a, b) => b.total - a.total);
    store.set(k, u); n++;
  }
  store.set("meta:scoring", { v: SCORING_VERSION });
  console.log(`[migrate] Recomputed scores of ${n} players`);
}

async function seedHistories() {
  let moved = 0, seeded = 0;
  // previous version kept histories inside the main database: move them out (and their likes)
  for (const k of store.keys("hist:")) {
    const u = k.slice(5), arr = store.get(k) || [], likes = store.get(rlkKey(u)) || {};
    for (const h of arr) if (h.lk) { likes[h.id] = h.lk; delete h.lk; }
    if (Object.keys(likes).length) store.set(rlkKey(u), likes);
    await store.histSet(u, arr); store.del(k); moved++;
  }
  // players with no history at all: start it with their best rolls
  for (const k of store.keys("user:")) {
    const u = store.get(k), l = lc(u.username);
    if (!(u.top || []).length || (await store.histGet(l)).length) continue;
    const arr = u.top.slice().sort((a, b) => (a.at || 0) - (b.at || 0)).map((r, i) => ({ id: -(u.top.length - i), n: r.n, t: r.total, p: r.pct, at: r.at || null, b: (r.badges || []).length }));
    await store.histSet(l, arr); seeded++;
  }
  if (moved || seeded) console.log(`[migrate] Roll history: ${moved} moved, ${seeded} seeded from best rolls`);
}

// playtime did not exist before: rebuild it from each player's roll history (gaps under 3 minutes count as playing)
async function seedPlaytime() {
  let n = 0;
  for (const k of store.keys("user:")) {
    const u = store.get(k);
    if (u.playV) continue;
    const ats = (await store.histGet(lc(u.username))).map((h) => h.at).filter(Boolean).sort((a, b) => a - b);
    let play = 0;
    for (let i = 1; i < ats.length; i++) { const g = ats[i] - ats[i - 1]; if (g > 0 && g <= IDLE_MS) play += g; }
    u.play = Math.max(u.play || 0, play); u.playV = 1; store.set(k, u); n++;
  }
  if (n) console.log(`[migrate] Playtime rebuilt for ${n} players`);
}

store.init().then(async () => {
  migrateScores();
  await seedHistories();
  await seedPlaytime();
  app.listen(PORT, () => console.log(`InfiniRoll running on http://localhost:${PORT}`));
  console.log(ADMINS.length ? `[admin] Admins: ${ADMINS.join(", ")}` : "[admin] No admin set (add ADMIN_USERS in the environment variables)");
  const shutdown = () => store.flush().finally(() => process.exit(0));
  process.on("SIGTERM", shutdown);
  process.on("SIGINT", shutdown);
});
